"use client";

import React, { useState, useMemo, useRef } from "react";
import { 
  Calendar as CalendarIcon, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  GraduationCap, 
  Heart, 
  AlertOctagon, 
  CheckCircle2, 
  Clock, 
  UploadCloud, 
  User,
  Users,
  ChevronRight,
  ShieldCheck,
  Search
} from "lucide-react";

// --- 1. CONFIGURATION (Simulating API Data) ---
const HOLIDAYS = [
  { date: "2026-01-26", name: "Republic Day" },
];

// This list can be as long as you want - the UI will scroll
const LEAVE_TYPES = [
  { id: "annual", label: "Annual Leave", icon: Plane, balance: 18, color: "text-blue-600", bg: "bg-blue-50", desc: "Vacation" },
  { id: "sick", label: "Sick Leave", icon: Stethoscope, balance: 12, color: "text-rose-600", bg: "bg-rose-50", desc: "Illness", requiresDoc: true },
  { id: "casual", label: "Casual Leave", icon: Briefcase, balance: 6, color: "text-amber-600", bg: "bg-amber-50", desc: "Personal" },
  { id: "comp", label: "Comp Off", icon: Umbrella, balance: 3, color: "text-emerald-600", bg: "bg-emerald-50", desc: "Overtime" },
  { id: "maternity", label: "Maternity", icon: Baby, balance: 90, color: "text-purple-600", bg: "bg-purple-50", desc: "Parental", requiresDoc: true },
  { id: "bereavement", label: "Bereavement", icon: Heart, balance: 5, color: "text-slate-600", bg: "bg-slate-100", desc: "Family Loss" },
  { id: "study", label: "Study Leave", icon: GraduationCap, balance: 0, color: "text-indigo-600", bg: "bg-indigo-50", desc: "Education" },
  { id: "lop", label: "Loss of Pay", icon: AlertOctagon, balance: 0, color: "text-red-600", bg: "bg-red-50", desc: "Unpaid" },
];

// Mock Team Data for the "Team Calendar" view
const TEAM_SCHEDULE = [
  { id: 1, name: "Sarah Jenkins", role: "Manager", avatar: "SJ", start: 20, end: 22, color: "bg-purple-100 text-purple-700" },
  { id: 2, name: "Mike Ross", role: "Frontend", avatar: "MR", start: 12, end: 14, color: "bg-orange-100 text-orange-700" },
  { id: 3, name: "Jessica P.", role: "Designer", avatar: "JP", start: 26, end: 28, color: "bg-blue-100 text-blue-700" },
];

const APPROVER = {
  name: "Sarah Jenkins",
  role: "Engineering Manager",
  avgTime: "4 Hours",
  avatar: "SJ"
};

export default function EliteAbsencePortal() {
  // --- STATE ---
  const [mode, setMode] = useState<"single" | "range">("range");
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [typeId, setTypeId] = useState("annual");
  const [halfDay, setHalfDay] = useState<"am" | "pm" | null>(null);
  const [reason, setReason] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- LOGIC ---
  const handleDateClick = (dateStr: string) => {
    if (mode === "single") {
      setRange({ start: dateStr, end: dateStr });
      setHalfDay(null);
    } else {
      if (!range.start || (range.start && range.end)) {
        setRange({ start: dateStr, end: "" });
      } else {
        const s = new Date(range.start);
        const e = new Date(dateStr);
        if (e < s) setRange({ start: dateStr, end: "" });
        else setRange({ ...range, end: dateStr });
      }
    }
  };

  const stats = useMemo(() => {
    if (!range.start || !range.end) return { days: 0, deduction: 0 };
    let d = 0, deduction = 0;
    let cur = new Date(range.start);
    let end = new Date(range.end);
    while (cur <= end) {
      const dateStr = cur.toISOString().split('T')[0];
      const isHoliday = HOLIDAYS.some(h => h.date === dateStr);
      const isWeekend = cur.getDay() === 0 || cur.getDay() === 6;
      
      if (!isHoliday && !isWeekend) {
        deduction += (range.start === range.end && halfDay) ? 0.5 : 1;
      }
      d++;
      cur.setDate(cur.getDate() + 1);
    }
    return { days: d, deduction };
  }, [range, halfDay]);

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;

  return (
    <div className="flex h-screen w-full flex-col bg-white text-slate-800 overflow-hidden font-sans">
      
      {/* 1. HEADER */}
      <header className="flex h-[60px] flex-none items-center justify-between border-b px-6 bg-white z-20">
        <div className="flex items-center gap-2">
          <div className="rounded-lg bg-slate-900 p-1.5 text-white"><CalendarIcon className="h-4 w-4" /></div>
          <span className="font-bold text-slate-900 text-lg">Absence<span className="text-slate-400">Manager</span></span>
        </div>
        <div className="flex items-center gap-4 bg-slate-50 px-3 py-1.5 rounded-full border border-slate-100">
           <div className="h-6 w-6 rounded-full bg-blue-600 text-white flex items-center justify-center text-[10px] font-bold">JD</div>
           <span className="text-xs font-bold text-slate-700">John Doe</span>
        </div>
      </header>

      {/* 2. MAIN WORKSPACE */}
      <div className="flex flex-1 overflow-hidden">
        
        {/* LEFT: LEAVE TYPES (Customizable List) */}
        <nav className="w-[260px] flex-none border-r bg-slate-50/50 flex flex-col">
           <div className="p-4 border-b border-slate-100 flex items-center justify-between">
              <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Leave Policy</span>
              <span className="text-[10px] text-blue-600 font-bold cursor-pointer">View All</span>
           </div>
           
           {/* Scrollable Area */}
           <div className="flex-1 overflow-y-auto p-3 space-y-1 custom-scrollbar">
              {LEAVE_TYPES.map((t) => (
                <button
                  key={t.id}
                  onClick={() => setTypeId(t.id)}
                  className={`group flex w-full items-start gap-3 rounded-xl p-3 text-left transition-all ${
                    typeId === t.id ? "bg-white shadow-md ring-1 ring-slate-200 z-10" : "hover:bg-slate-100"
                  }`}
                >
                  <div className={`mt-0.5 rounded-lg p-1.5 ${t.bg} ${t.color}`}><t.icon className="h-4 w-4" /></div>
                  <div className="flex-1">
                    <div className="flex justify-between items-center">
                        <span className={`text-xs font-bold ${typeId === t.id ? "text-slate-900" : "text-slate-600"}`}>{t.label}</span>
                        {typeId === t.id && <ChevronRight className="h-3 w-3 text-slate-400" />}
                    </div>
                    <div className="text-[10px] text-slate-400 mt-0.5">{t.desc}</div>
                    <div className={`mt-2 text-[10px] font-bold px-2 py-0.5 rounded w-fit ${typeId === t.id ? "bg-slate-100 text-slate-700" : "bg-slate-200/50 text-slate-500"}`}>
                        {t.balance} Days Left
                    </div>
                  </div>
                </button>
              ))}
           </div>
        </nav>

        {/* CENTER: CALENDAR & TEAM SCHEDULE */}
        <main className="flex-1 flex flex-col bg-white relative min-w-0">
          
          {/* Calendar Toolbar */}
          <div className="flex h-[60px] flex-none items-center justify-between border-b px-6">
             <h2 className="text-lg font-bold flex items-center gap-2">January 2026 <span className="text-slate-300 font-light">|</span> <span className="text-xs font-medium text-slate-500">Select Dates</span></h2>
             
             <div className="flex bg-slate-100 p-1 rounded-lg">
                <button onClick={() => { setMode("single"); setRange({start:"", end:""}); }} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${mode === "single" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}>Single Day</button>
                <button onClick={() => { setMode("range"); setRange({start:"", end:""}); }} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${mode === "range" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}>Range</button>
             </div>
          </div>

          {/* Calendar Grid (60% Height) */}
          <div className="flex-none h-[55%] p-6 overflow-y-auto border-b border-slate-100">
             <div className="grid grid-cols-7 gap-2 h-full content-start">
                {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                  <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase mb-2">{d}</div>
                ))}
                
                {[null, null, null].map((_, i) => <div key={`e-${i}`} />)}

                {Array.from({ length: 31 }).map((_, i) => {
                  const day = i + 1;
                  const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                  const holiday = HOLIDAYS.find(h => h.date === dateStr);
                  const isWeekend = new Date(2026, 0, day).getDay() % 6 === 0;
                  const isSelected = range.start === dateStr || range.end === dateStr;
                  const inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;

                  return (
                    <button
                      key={day}
                      onClick={() => handleDateClick(dateStr)}
                      disabled={isWeekend && !holiday}
                      className={`
                        relative h-full min-h-[50px] rounded-xl border text-left p-2 transition-all
                        ${isSelected ? "bg-slate-900 text-white border-slate-900 shadow-md scale-[1.02] z-10" : ""}
                        ${inRange ? "bg-blue-50 text-blue-700 border-blue-100" : ""}
                        ${holiday && !inRange && !isSelected ? "bg-rose-50 border-rose-100" : ""}
                        ${isWeekend && !inRange && !isSelected ? "bg-slate-50 border-slate-50 text-slate-300" : "bg-white border-slate-100 hover:border-blue-400"}
                      `}
                    >
                      <span className="text-sm font-bold">{day}</span>
                      {holiday && <span className={`absolute bottom-1 right-1 text-[8px] font-bold px-1.5 rounded ${isSelected ? "text-white bg-white/20" : "text-rose-600 bg-rose-100"}`}>{holiday.name}</span>}
                    </button>
                  );
                })}
             </div>
          </div>

          {/* Team Schedule (40% Height) */}
          <div className="flex-1 bg-slate-50/50 p-6 flex flex-col min-h-0">
             <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-2">
                   <Users className="h-4 w-4 text-slate-400" />
                   <span className="text-xs font-bold uppercase text-slate-500">Team Schedule (Jan)</span>
                </div>
                <div className="flex gap-2">
                   <span className="h-2 w-2 rounded-full bg-slate-300"></span>
                   <span className="text-[10px] text-slate-400">Today</span>
                </div>
             </div>
             
             <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
                {TEAM_SCHEDULE.map(person => (
                   <div key={person.id} className="flex items-center gap-4">
                      <div className="w-24 shrink-0 flex items-center gap-2">
                         <div className="h-6 w-6 rounded-full bg-white border border-slate-200 flex items-center justify-center text-[9px] font-bold text-slate-600">{person.avatar}</div>
                         <span className="text-[10px] font-bold text-slate-600 truncate">{person.name.split(' ')[0]}</span>
                      </div>
                      <div className="flex-1 h-8 bg-white rounded-lg border border-slate-200 relative overflow-hidden">
                         {/* This mimics a Gantt bar - Start at day X, width Y% */}
                         <div 
                           className={`absolute top-1 bottom-1 rounded-md text-[9px] font-bold flex items-center pl-2 ${person.color}`}
                           style={{ 
                              left: `${(person.start / 31) * 100}%`, 
                              width: `${((person.end - person.start) / 31) * 100}%` 
                           }}
                         >
                            Out
                         </div>
                      </div>
                   </div>
                ))}
             </div>
          </div>
        </main>

        {/* RIGHT: APPROVER & FORM (300px) */}
        <aside className="w-[300px] flex-none border-l bg-white flex flex-col shadow-xl z-20">
           
           {/* 1. APPROVER CARD */}
           <div className="p-5 border-b border-slate-100">
              <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-3 block">Approval Workflow</span>
              <div className="flex items-center gap-3 p-3 rounded-xl border border-slate-100 bg-slate-50">
                 <div className="h-8 w-8 rounded-full bg-purple-100 text-purple-700 flex items-center justify-center font-bold text-xs">{APPROVER.avatar}</div>
                 <div className="flex-1">
                    <p className="text-xs font-bold text-slate-900">{APPROVER.name}</p>
                    <p className="text-[10px] text-slate-500">{APPROVER.role}</p>
                 </div>
                 <div className="text-[9px] font-medium text-emerald-600 bg-emerald-50 px-1.5 py-0.5 rounded">~{APPROVER.avgTime}</div>
              </div>
           </div>

           {/* 2. SUMMARY */}
           <div className="p-5 border-b border-slate-100">
              <div className="bg-blue-50/50 rounded-xl p-4 border border-blue-100 space-y-3">
                 <div className="flex justify-between items-center text-xs">
                    <span className="text-slate-500">Start Date</span>
                    <span className="font-bold text-slate-900">{range.start ? range.start : "-"}</span>
                 </div>
                 <div className="flex justify-between items-center text-xs">
                    <span className="text-slate-500">Return Date</span>
                    <span className="font-bold text-slate-900">{range.end ? "Calculated..." : "-"}</span>
                 </div>
                 <div className="h-px bg-blue-200/50"></div>
                 <div className="flex justify-between items-center">
                    <span className="text-xs font-bold text-slate-600">Total Days</span>
                    <span className="text-xl font-black text-blue-600">{stats.deduction}</span>
                 </div>
              </div>
           </div>

           {/* 3. INPUTS */}
           <div className="flex-1 p-5 space-y-4 overflow-y-auto">
              {mode === "single" && range.start && (
                <div>
                   <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block">Duration</label>
                   <div className="grid grid-cols-3 gap-2 bg-slate-100 p-1 rounded-lg">
                      <button onClick={() => setHalfDay(null)} className={`text-[10px] font-bold py-2 rounded ${!halfDay ? "bg-white shadow text-slate-900" : "text-slate-400"}`}>Full</button>
                      <button onClick={() => setHalfDay("am")} className={`text-[10px] font-bold py-2 rounded ${halfDay === "am" ? "bg-white shadow text-slate-900" : "text-slate-400"}`}>AM</button>
                      <button onClick={() => setHalfDay("pm")} className={`text-[10px] font-bold py-2 rounded ${halfDay === "pm" ? "bg-white shadow text-slate-900" : "text-slate-400"}`}>PM</button>
                   </div>
                </div>
              )}

              <div>
                 <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block">Reason</label>
                 <textarea 
                   className="w-full h-20 rounded-xl border border-slate-200 p-3 text-xs font-medium focus:ring-2 focus:ring-slate-900 outline-none resize-none"
                   placeholder="Enter details..."
                   value={reason}
                   onChange={(e) => setReason(e.target.value)}
                 />
              </div>

              {selectedType.requiresDoc && (
                 <div>
                    <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block flex justify-between">
                       <span>Attachment</span> <span className="text-rose-500">* Required</span>
                    </label>
                    <div 
                      onClick={() => fileInputRef.current?.click()}
                      className="border-2 border-dashed border-slate-200 rounded-xl h-16 flex items-center justify-center cursor-pointer hover:bg-slate-50 transition-colors gap-2"
                    >
                       <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                       <UploadCloud className="h-4 w-4 text-slate-400" />
                       <span className="text-[10px] font-bold text-slate-500">{file ? "File Attached" : "Upload Proof"}</span>
                    </div>
                 </div>
              )}
           </div>

           {/* 4. SUBMIT */}
           <div className="p-5 border-t bg-slate-50">
              <button 
                disabled={!range.start || (selectedType.requiresDoc && !file)}
                className="w-full bg-slate-900 text-white py-3.5 rounded-xl font-bold text-sm shadow-lg hover:bg-black disabled:bg-slate-300 transition-all"
              >
                 Submit Request
              </button>
           </div>
        </aside>

      </div>
    </div>
  );
}